"% Monte Carlo robustness screening for closed-loop short-period spec

% 1. Define Nominal System
% States x = [u, w, q, theta]
g = 32.174;
V = 740.0;
Xu = -0.006;
Xw = 0.033;
Zu = -0.027;
Zw = -0.66;
Mw = -0.0046;
Mq = -0.78;

A_nom = [Xu,  Xw,  0,   -g;
         Zu,  Zw,  V,    0;
         0,   Mw,  Mq,   0;
         0,   0,   1,    0];

B = [0; -5.5; -4.5; 0];

% 2. Design State Feedback Gain K
% Goal: Place short-period poles at omega_n=2.1, zeta=0.55
% Constraint: Phugoid held at open-loop -> K = [0, *, *, 0]

% Short-period subsystem (w, q) states
A_sp = A_nom(2:3, 2:3);
B_sp = B(2:3);

% Desired poles
wn_des = 2.1;
z_des = 0.55;
p_des = -z_des*wn_des + 1i*wn_des*sqrt(1-z_des^2);

% Compute gains for SP subsystem
K_sp = place(A_sp, B_sp, [p_des, conj(p_des)]);

% Construct full K
K = [0, K_sp, 0];

% 3. Monte Carlo Setup
N = 200;
pct = 0.20; % 20% uncertainty

% Generate deterministic samples with specific seeds
rng(20260828);
f_Mw = 1 + pct * (2*rand(N,1) - 1);

rng(20261828);
f_Zw = 1 + pct * (2*rand(N,1) - 1);

rng(20262828);
f_Mq = 1 + pct * (2*rand(N,1) - 1);

% 4. Evaluation Loop
pass_count = 0;

for i = 1:N
    % Create perturbed A matrix
    A_i = A_nom;

    % Apply uncertainties to Mw, Zw, Mq
    A_i(2,2) = A_i(2,2) * f_Zw(i); % Zw
    A_i(3,2) = A_i(3,2) * f_Mw(i); % Mw
    A_i(3,3) = A_i(3,3) * f_Mq(i); % Mq

    % Closed-loop system matrix
    A_cl = A_i - B*K;

    % Compute eigenvalues
    ev = eig(A_cl);

    % Identify Short-Period poles
    % SP poles are the fast poles (highest natural frequency)
    % Phugoid poles are very slow (approx 0.06 rad/s)
    % Sort poles by magnitude (natural frequency) descending
    [mags, sortIdx] = sort(abs(ev), 'descend');

    % The first two are the SP poles
    sp_p1 = ev(sortIdx(1));
    sp_p2 = ev(sortIdx(2));

    % Calculate omega_n and zeta from the poles
    % For a 2nd order system s^2 + 2*zeta*wn*s + wn^2 = (s - p1)(s - p2)
    % wn = sqrt(p1 * p2)
    % zeta = -(p1 + p2) / (2 * wn)

    p_prod = sp_p1 * sp_p2;
    p_sum = sp_p1 + sp_p2;

    % Check validity (product must be positive for real wn)
    if p_prod > 0
        wn = sqrt(p_prod);
        zeta = -p_sum / (2 * wn);

        % Check Spec
        if (wn >= 2.0) && (wn <= 2.2) && (zeta >= 0.52)
            pass_count = pass_count + 1;
        end
    end
end

% 5. Output Results
result.pass_fraction = pass_count / N;
result.failing_case_count = N - pass_count;

% Write to JSON
fid = fopen('result.json', 'w');
fprintf(fid, '%s', jsonencode(result));
fclose(fid);"
